package com.xuhang.mealops.inventory.infrastructure.persistence;
import static org.assertj.core.api.Assertions.*; import java.math.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.context.annotation.Import; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.jdbc.core.JdbcTemplate; import com.xuhang.mealops.ingredient.application.IngredientRepository; import com.xuhang.mealops.ingredient.domain.*; import com.xuhang.mealops.inventory.application.*; import com.xuhang.mealops.inventory.domain.*; import com.xuhang.mealops.measurement.domain.*; import com.xuhang.mealops.support.PostgresTestConfiguration;
@SpringBootTest @Import(PostgresTestConfiguration.class) class InventoryConsumptionPersistenceIT { @Autowired InventoryBatchRepository batches; @Autowired InventoryTransactionRepository transactions; @Autowired IngredientRepository ingredients; @Autowired JdbcTemplate jdbc;
 @Test void verifiesV4VersionCasCandidatesAndLedger(){ Ingredient i=ingredients.create(Ingredient.newIngredient(IngredientName.of("CAS "+UUID.randomUUID()))); InventoryBatch b=batches.create(InventoryBatch.newBatch(i.id(),Quantity.of(new BigDecimal("500"),Unit.GRAM),LocalDate.of(2026,8,2))); assertThat(b.version()).isZero(); assertThat(batches.findConsumableBatches(i.id(),Unit.GRAM)).extracting(InventoryBatch::id).containsExactly(b.id()); assertThat(batches.consumeWithVersion(b.id(),new BigDecimal("200"),0,"g")).isTrue(); InventoryBatch after=batches.findById(b.id()).orElseThrow(); assertThat(after.remainingQuantity().amount()).isEqualByComparingTo("300"); assertThat(after.version()).isEqualTo(1); assertThat(batches.consumeWithVersion(b.id(),new BigDecimal("200"),0,"g")).isFalse(); assertThat(batches.consumeWithVersion(b.id(),new BigDecimal("400"),1,"g")).isFalse(); assertThat(batches.findById(b.id()).orElseThrow().remainingQuantity().amount()).isEqualByComparingTo("300"); long tx=transactions.createConsumption(i.id(),new BigDecimal("200"),"g",List.of(new InventoryConsumptionAllocation(1,b.id(),0,new BigDecimal("200"),new BigDecimal("500"),new BigDecimal("300"),"g"))); assertThat(tx).isPositive(); assertThat(jdbc.queryForObject("select transaction_type from inventory_transaction where id=?",String.class,tx)).isEqualTo("CONSUME"); assertThat(jdbc.queryForObject("select amount from inventory_transaction_allocation where transaction_id=?",BigDecimal.class,tx)).isEqualByComparingTo("200"); }
 @Test void rejectsLedgerAndVersionConstraintViolations(){ Ingredient i=ingredients.create(Ingredient.newIngredient(IngredientName.of("Constraint "+UUID.randomUUID()))); assertThatThrownBy(()->jdbc.update("insert into inventory_batch(ingredient_id,remaining_amount,unit_code,version) values(?,?,?,?)",i.id(),BigDecimal.ONE,"g",-1)).isInstanceOf(DataIntegrityViolationException.class); assertThatThrownBy(()->jdbc.update("insert into inventory_transaction(transaction_type,ingredient_id,amount,unit_code) values(?,?,?,?)", "ADJUST",i.id(),BigDecimal.ONE,"g")).isInstanceOf(DataIntegrityViolationException.class); assertThatThrownBy(()->jdbc.update("insert into inventory_transaction(transaction_type,ingredient_id,amount,unit_code) values(?,?,?,?)", "CONSUME",i.id(),BigDecimal.ZERO,"g")).isInstanceOf(DataIntegrityViolationException.class); assertThatThrownBy(()->jdbc.update("insert into inventory_transaction(transaction_type,ingredient_id,amount,unit_code) values(?,?,?,?)", "CONSUME",i.id(),BigDecimal.ONE,"kg")).isInstanceOf(DataIntegrityViolationException.class); }
}
